WITH flattened AS (SELECT id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo FROM (SELECT id, created_at, coupon_codes, EXPLODE_OUTER(items) AS elem FROM carts) e) SELECT CASE WHEN qty >= 5 THEN 'LARGE' ELSE 'SMALL' END AS qty_tier, ROUND(AVG(qty), 2) AS avg_qty, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids FROM flattened GROUP BY CASE WHEN qty >= 5 THEN 'LARGE' ELSE 'SMALL' END;
